# -*- coding: utf-8 -*-
"""The sshconnection Module creates and controls SSH Connections between Robot
Workspace Lab PC and any remote PC.

The SshConnection Module is based on Robot Framework SSHLibrary test library.

:copyright: NSN
:author: Binbin Guo
:contact: binbguo.ext@nsn.com
"""
import logging
import paramiko
from SSHLibrary import SSHClient
from contextlib import contextmanager
from functools import partial


class EstablishSsh(object):
    """Establish ssh session."""

    def __init__(self, ssh_method):
        self.ssh_method = ssh_method
        self._log = logging.getLogger(__name__)

    def __call__(self, *args, **kwargs):
        with self.establish_ssh(args[0]):
            return self.ssh_method(*args, **kwargs)

    def __get__(self, obj, objtype):
        """Support instance methods."""
        return partial(self.__call__, obj)

    @contextmanager
    def establish_ssh(self, ssh_connection):
        """Setup and teardown ssh connection in specific context.

        :param ssh_connection:      ssh client.

        """
        try:
            if hasattr(ssh_connection, "_setup"):
                yield ssh_connection._setup()
        finally:
            if hasattr(ssh_connection, "_teardown"):
                ssh_connection._teardown()


class SshConnection(object):
    """SshConnecion class creates SSH Connection between Robot workspace Lab PC
       and a remote host

    :param String host: hostname or IP address
    :param String user: user name
    :param String password: user password
    :param Integer port: SSH Connection port
    :param String prompt: SSH Connection user prompt (default is "$ ")
    :param Integer timeout: SSH Connection timeout
    """

    def __init__(self, host, user, password, port=22, prompt="$ ",
                 timeout=15, **kwargs):

        self._sshClt = SSHClient(host=host,
                                 prompt=prompt,
                                 timeout=timeout,
                                 port=port)

        self.__host = host
        self.__user = user
        self.__password = password
        self.__port = int(port)
        self.__prompt = prompt
        self.__os = None
        self.__name = "%s@%s:%d %#x" % (user, host, int(port), id(self))
        self._log = logging.getLogger(__name__)

    host = property(lambda s: s.__host)
    prompt = property(lambda s: s.__prompt)
    user = property(lambda s: s.__user)

    def _setup(self):
        exception_msg = ''
        nTries = 3
        for i in range(1, nTries + 1):
            try:
                self._log.info("[%s] login #%d, password = <%s>" % (
                    self.__name,
                    i,
                    self.__password))
                if ('look_for_keys' in self._sshClt.login.__code__.co_varnames):
                    ret = self._sshClt.login(
                        self.__user, self.__password, look_for_keys=True)
                else:
                    ret = self._sshClt.login(self.__user, self.__password)
                # self._sshClt.enable_logging("/tmp/sshclient.log")
                # if search("Resource temporarily unavailable", ret):
                    # raise RuntimeError("temporary problem: <%s>" % ret)
                self._log.info(
                    "[%s] login #%d, result = <%s>" %
                    (self.__name, i, ret))
                break
            except Exception as e:
                logging.info(
                    "[%s] login #%d, exception = <%s>" %
                    (self.__name, i, e))
                if i == nTries:
                    raise

    def _teardown(self):
        if self._sshClt:
            self._sshClt.close()
            self._sshClt = None
            self._log.info("[%s] connection closed" % self.__name)

    def execute(self, cmd):
        """ Execute command on SSH Connection.

        :param String cmd: command string
        """
        try:
            self._log.debug("executed command is: %s" % cmd)
            out, err, rc = self._sshClt.execute_command(cmd)
        except paramiko.SSHException:
            self._teardown()

        out = out.strip()
        err = err.strip()
        # self._log.info("[%s] stdout <%s>, stderr = <%s>, rc = <%s>" % (self.__name, out, err, rc))
        return out, err, rc

    def get_file(self, src, dst):
        """ Get file using SSH Connection.

        :param String src: source file
        :param String dst: destination file
        """
        self._log.info("[%s] source = <%s>, destination = <%s>" % (
            self.__name,
            src,
            dst))
        return self._sshClt.get_file(src, dst)

    def put_file(self, src, dst):
        """ Put file using SSH Connection.

        :param String src: source file
        :param String dst: destination file
        """
        self._log.info("[%s] source = <%s>, destination = <%s>" % (
            self.__name,
            src,
            dst))
        return self._sshClt.put_file(src, dst, "0777")

    def write(self, text):
        """ Write text on SSH Connection.

        :param String text: text string
        """
        self._sshClt.write(text)

    def read_until_regex(self, regex, timeout=None):
        """ Read until regular expression matches the SSH Connection output.

        :param String regex: read until regular expression
        :param Integer timeout: read until timeout (default is None)
        """
        oldTimeout = self._sshClt.config.timeout
        self._log.info(
            "[%s] regular expression = <%s>, timeout = <%s>" %
            (self.__name, regex, timeout if timeout is not None else oldTimeout))
        if timeout is not None:
            self._sshClt.config.update(timeout=timeout)
        try:
            out = self._sshClt.read_until_regexp(regex)
        except Exception as e:
            self._log.info("[%s] exception = <%s>" % (self.__name, e))
            raise
        else:
            self._log.info("[%s] output = <%s>" % (self.__name, out))
            return out
        finally:
            if timeout is not None:
                self._sshClt.config.update(timeout=oldTimeout)

    def read(self):
        """ Read all output from SSH Connection.
        """
        out = self._sshClt.read()
        if out:
            self._log.info("[%s] output = <%s>" % (self.__name, out))
        return out

    def start_command(self, command):
        """Starts command execution on remote host and return immediately.

        This keyword doesn't return anything. Use `Read Command Output` to read
        the output generated from command execution.

        Note that the `Read Command Output` keyword always reads the output of
        the most recently started command.

        Example:
        | Start Command | some command |
        """
        self._log.info("Starting command '%s'" % command)
        self._command = command
        self._sshClt.start_command(command)

    def _output_options(self, stdout, stderr, rc):
        # Handle legacy options for configuring returned outputs
        if not isinstance(stdout, str):
            return stdout, stderr, rc
        stdout = stdout.lower()
        if stdout == 'stderr':
            return False, True, rc
        if stdout == 'both':
            return True, True, rc
        return stdout, stderr, rc

    def read_command_output(self, return_stdout=True, return_stderr=False,
                            return_rc=False):
        """Reads and returns/logs output (stdout and/or stderr) of a command.

        Command must have been started using `Start Command` before this
        keyword can be used.

        See `Execute Command` for examples about how the return value can
        be configured using `return_stdout`, `return_stderr` and `return_rc`.
        """
        self._log.info("Reading output of command '%s'" % self._command)
        opts = self._output_options(return_stdout, return_stderr, return_rc)
        stdout, stderr, rc = self._sshClt.read_command_output()
        return self._return_command_output(stdout, stderr, rc, *opts)
